<template>
  <div class="quick-settings">
    <aside class="action-list-card">
      <div class="action-list-head"><div><strong>快捷指令</strong><small>{{ actions.length }} 条</small></div><button type="button" class="new-button" @click="selectNew">＋ 新建</button></div>
      <button v-for="action in actions" :key="action.id" type="button" :class="['action-row',{active:selectedId===action.id}]" :aria-pressed="selectedId===action.id" @click="emit('update:selectedId',action.id)">
        <span class="action-row-copy"><strong>{{ action.name }}</strong><small>需求开发 · {{ action.skills.length }} Skills</small></span>
        <span v-if="action.missingSkillIds.length" class="invalid-pill">需修复</span><span v-else :class="['action-status', { enabled: action.enabled }]">{{ action.enabled ? '已启用' : '已停用' }}</span>
      </button>
      <div v-if="!actions.length" class="action-empty"><span>⌘</span><strong>还没有快捷指令</strong><small>把重复的需求开发步骤变成一键操作。</small></div>
    </aside>

    <form class="action-editor" @submit.prevent="submit">
      <div class="editor-head"><div><div class="kicker">{{ selectedAction ? 'EDIT COMMAND' : 'NEW COMMAND' }}</div><h2>{{ selectedAction ? selectedAction.name : '新建快捷指令' }}</h2></div><label class="enabled-toggle"><input v-model="form.enabled" type="checkbox" /><span>启用</span></label></div>
      <p v-if="selectedAction" class="editor-meta" :title="selectedAction.sourceConversationId ? `来源会话：${selectedAction.sourceConversationId}` : ''">v{{ selectedAction.revision }} · {{ selectedAction.lastEditedVia === 'agent' ? '由需求会话内 AI 更新' : '由设置页更新' }}</p>
      <p v-if="selectedAction?.missingSkillIds.length" class="warning" role="alert"><span>以下 Skill 已失效：{{ missingSkillNames }}。移除后可重新选择。</span><button type="button" @click="removeMissingSkills">移除失效引用</button></p>
      <label for="quick-action-name">指令名称</label><input ref="nameInput" id="quick-action-name" v-model="form.name" class="field" maxlength="80" placeholder="例如：检查实现并补测试" />
      <label for="quick-action-prompt">执行内容</label><textarea ref="promptInput" id="quick-action-prompt" v-model="form.prompt" class="field prompt-field" maxlength="20000" placeholder="描述点击后要直接发送给 Codex 的完整任务…" />
      <div class="field-label"><label for="quick-action-skill-search">默认 Skills <span>可多选</span></label><small>执行时会作为结构化 Skill 引用发送</small></div>
      <input id="quick-action-skill-search" v-model="skillQuery" class="field skill-search" type="search" placeholder="搜索 Skill…" />
      <div class="skill-picker">
        <label v-for="skill in filteredSkills" :key="skill.id" :class="['skill-option',{disabled:!isSkillAvailable(skill)}]"><input v-model="form.skillIds" type="checkbox" :value="skill.id" :disabled="!isSkillAvailable(skill)" /><span><strong>{{ skill.displayName || skill.name }}</strong><small>{{ skill.description || skill.path }}<template v-if="sameNameSkills(skills, skill).length"> · {{ skill.path }}</template></small></span><em>{{ skillSourceLabel(skill.source) }}</em></label>
        <p v-if="!filteredSkills.length" class="no-results">没有匹配的 Skill。</p>
      </div>
      <fieldset><legend>应用场景</legend><label class="scene-option"><input v-model="form.scenes" type="checkbox" value="demand-development" /><span><strong>需求开发</strong><small>显示在 Demand 会话输入框上方</small></span></label></fieldset>
      <p v-if="validationError" class="form-error" role="alert">{{ validationError }}</p><p v-else-if="message" class="success-message" role="status">{{ message }}</p>
      <div class="editor-actions">
        <div><button v-if="selectedAction" type="button" class="delete-button" :disabled="saving" @click="requestDelete">{{ confirmingDelete ? '再点一次确认删除' : '删除指令' }}</button></div>
        <button type="submit" class="save-button" :aria-disabled="saving" :aria-busy="saving">{{ saving ? '保存中…' : selectedAction ? '保存修改' : '创建指令' }}</button>
      </div>
    </form>
  </div>
</template>

<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import type { QuickAction, QuickActionInput, WorkspaceSkill } from '../api'
import { filterSkills, sameNameSkills, skillSourceLabel } from '../workbenchUi'

const props = defineProps<{ actions: QuickAction[]; skills: WorkspaceSkill[]; selectedId: string; saving: boolean; message: string }>()
const emit = defineEmits<{ 'update:selectedId':[id:string]; save:[input:QuickActionInput & {id?:string}]; delete:[id:string] }>()
const nameInput=ref<HTMLInputElement|null>(null); const promptInput=ref<HTMLTextAreaElement|null>(null)
const skillQuery=ref(''); const validationError=ref(''); const confirmingDelete=ref(false)
const form=reactive<QuickActionInput>({name:'',prompt:'',skillIds:[],scenes:['demand-development'],enabled:true})
const selectedAction=computed(()=>props.actions.find(action=>action.id===props.selectedId))
const filteredSkills=computed(()=>filterSkills(props.skills,skillQuery.value))
const missingSkillNames=computed(()=>selectedAction.value?.skills.filter(skill=>skill.status!=='available').map(skill=>skill.name).join('、')||selectedAction.value?.missingSkillIds.join('、')||'未知 Skill')
function isSkillAvailable(skill:WorkspaceSkill):boolean{return skill.status==='available'&&skill.modelInvocable}
function removeMissingSkills():void{const availableIds=new Set(props.skills.filter(isSkillAvailable).map(skill=>skill.id));form.skillIds=form.skillIds.filter(id=>availableIds.has(id));validationError.value=''}
function reset(action?:QuickAction):void{form.name=action?.name??'';form.prompt=action?.prompt??'';form.skillIds=[...(action?.skillIds??[])];form.scenes=[...(action?.scenes??['demand-development'])];form.enabled=action?.enabled??true;skillQuery.value='';validationError.value='';confirmingDelete.value=false}
watch(selectedAction,action=>reset(action),{immediate:true})
function selectNew():void{emit('update:selectedId','');reset()}
function submit():void{if(props.saving)return;validationError.value='';if(!form.name.trim()){validationError.value='请输入指令名称。';nameInput.value?.focus();return}if(!form.prompt.trim()){validationError.value='请输入执行内容。';promptInput.value?.focus();return}if(!form.scenes.length){validationError.value='至少选择一个应用场景。';return}const unavailable=form.skillIds.filter(id=>!props.skills.some(skill=>skill.id===id&&isSkillAvailable(skill)));if(unavailable.length){validationError.value='有已失效的 Skill，请重新选择。';return}emit('save',{...(selectedAction.value?{id:selectedAction.value.id}:{}),name:form.name.trim(),prompt:form.prompt.trim(),skillIds:[...form.skillIds],scenes:[...form.scenes],enabled:form.enabled})}
function requestDelete():void{if(!selectedAction.value)return;if(!confirmingDelete.value){confirmingDelete.value=true;return}emit('delete',selectedAction.value.id);confirmingDelete.value=false}
</script>

<style scoped>
.quick-settings{display:grid;grid-template-columns:300px minmax(0,1fr);gap:16px;max-width:1120px;padding:30px 36px 60px;margin:0 auto}.action-list-card,.action-editor{background: var(--surface-panel);border: 1px solid var(--border-default);border-radius: var(--radius-panel);box-shadow: var(--shadow-panel);}.action-list-card{align-self:start;overflow:hidden}.action-list-head{display:flex;align-items:center;justify-content:space-between;padding:17px 18px;border-bottom: 1px solid var(--border-default);}.action-list-head div{display:flex;align-items:baseline;gap:8px}.action-list-head small{color: var(--ink-tertiary);font-size:12px}.new-button{min-height:44px;padding:7px 12px;color: var(--accent);background: var(--surface-panel);border:0;border-radius: var(--radius-control);font-size:11px;font-weight:700}.action-row{display:flex;align-items:center;gap:10px;width:100%;min-height:64px;padding:12px 16px;color: var(--ink-primary);background: var(--surface-panel);border:0;border-bottom: 1px solid var(--border-default);text-align:left}.action-row:hover{background:var(--surface-subtle)}.action-row.active{background:var(--accent-subtle);box-shadow:inset 3px 0 var(--accent)}.action-row-copy{min-width:0;flex:1}.action-row-copy strong,.action-row-copy small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.action-row-copy small{margin-top:3px;color: var(--ink-tertiary);font-size:12px}.action-status{flex-shrink:0;padding:3px 6px;color:var(--ink-secondary);background:var(--surface-subtle);border-radius:var(--radius-control);font-size:11px}.action-status.enabled{color:var(--success);background:var(--success-bg)}.invalid-pill{padding:3px 6px;color: var(--warning);background: var(--warning-bg);border-radius:999px;font-size:11px}.action-empty{display:flex;flex-direction:column;align-items:center;padding:45px 24px;color: var(--ink-tertiary);text-align:center}.action-empty span{font-size:25px}.action-empty strong{margin-top:8px;color: var(--ink-secondary);}.action-empty small{margin-top:4px}.action-editor{padding:25px}.editor-head{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:22px}.kicker{color: var(--ink-tertiary);font-size:11px;font-weight:800;letter-spacing:.15em}.editor-head h2{margin:6px 0 0;font-size:19px;overflow-wrap:anywhere}.editor-head>div{min-width:0}.enabled-toggle{flex-shrink:0}.editor-head{gap:16px}.enabled-toggle{display:flex!important;align-items:center;gap:7px;min-height:44px;padding:0 11px;background: var(--surface-subtle);border-radius: var(--radius-control)}.action-editor>label,.field-label label{display:block;color: var(--ink-secondary);font-size:13px;font-weight:750}.field-label{display:flex;justify-content:space-between;gap:16px}.field-label span,.field-label small{color: var(--ink-tertiary);font-size:12px;font-weight:500}.field{width:100%;min-height:44px;margin:7px 0 17px;padding:10px 12px;color: var(--ink-primary);background: var(--surface-panel);border: 1px solid var(--border-default);border-radius: var(--radius-control);font:inherit}.field:focus{border-color: var(--accent-border);outline: 3px solid var(--accent-border);}.prompt-field{min-height:150px;resize:vertical;line-height:1.65}.skill-search{margin-bottom:8px}.skill-picker{max-height:230px;overflow:auto;border: 1px solid var(--border-default);border-radius: var(--radius-panel)}.skill-option{display:flex;align-items:center;gap:10px;min-height:55px;padding:9px 12px;border-bottom: 1px solid var(--border-default);}.skill-option:last-child{border-bottom:0}.skill-option>span{min-width:0;flex:1}.skill-option strong,.skill-option small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.skill-option strong{font-size:13px}.skill-option small{color: var(--ink-tertiary);font-size:11px}.skill-option em{color: var(--ink-tertiary);font-size:11px;font-style:normal}.skill-option.disabled{opacity:.5}.no-results{padding:20px;color: var(--ink-tertiary);text-align:center}fieldset{padding:14px;margin:18px 0;border: 1px solid var(--border-default);border-radius: var(--radius-panel)}legend{padding:0 6px;color: var(--ink-secondary);font-size:13px;font-weight:750}.scene-option{display:flex;align-items:center;gap:10px}.scene-option span{display:block}.scene-option strong,.scene-option small{display:block}.scene-option small{color: var(--ink-tertiary);font-size:12px}.warning,.form-error,.success-message{padding:10px 12px;border-radius: var(--radius-control);font-size:11px}.warning,.form-error{color: var(--warning);background: var(--warning-bg);}.success-message{color: var(--success);background: var(--surface-subtle);}.editor-actions{display:flex;align-items:center;justify-content:space-between;margin-top:22px}.save-button,.delete-button{min-height:44px;padding:8px 15px;border-radius: var(--radius-control);font-weight:700}.save-button{color: var(--on-accent);background: var(--accent);border: 1px solid var(--accent-border);}.delete-button{color: var(--danger);background: var(--surface-panel);border: 1px solid var(--danger-border);}@media(max-width:900px){.quick-settings{grid-template-columns:1fr;padding:22px}.action-list-card{max-height:270px;overflow:auto}}
.save-button[aria-disabled="true"]{opacity:.55;cursor:wait}
.editor-meta{margin:-14px 0 18px;color: var(--ink-tertiary);font-size:12px}
.action-list-card,.action-editor,fieldset{min-width:0}
.warning{display:flex;align-items:center;justify-content:space-between;gap:12px}.warning button{flex:0 0 auto;min-height:36px;padding:6px 10px;color: var(--warning);background: var(--surface-panel);border: 1px solid var(--warning-border);border-radius: var(--radius-control);font-size:12px;font-weight:700}@media(max-width:900px){.warning{align-items:flex-start;flex-direction:column}}
@media(max-width:600px){.field-label{flex-direction:column;gap:4px}.skill-option{flex-wrap:wrap}.skill-option em{margin-left:24px}.action-editor{padding:18px}.quick-settings{padding:16px}.field{font-size:16px}}
</style>
